export const NEW_SPECIES: NewSpecies[] = [
  { year: 2026, group: "Amphibians", article: "Odorrana nagao", scientific: "Odorrana nagao", said: "Odorrana nagao, also known as the Nagao odorous frog or Ếch đá na-gao in Vietnamese, is a species of frog that belongs to the family Ranidae. It can be found in northern Vietnam. They are a nocturnal species being found on rocks located inside caves or near their entrances. It is a medium-sized species with males being smaller than females at around 37.4 mm while females range from 47.1 to 54.7 mm in length. This species was named after the Nagao Natural Environment Foundation located in Japan.", where: "Found in northern Vietnam" },
  { year: 2026, group: "Amphibians", article: "Nymphargus dajomesae", scientific: "Nymphargus dajomesae", said: "Nymphargus dajomesae, commonly known as Dajomes glassfrog, is a species of frog in the family Centrolenidae. The body is yellowish-green to dark-green, and parts of the peritonea are white. The species is endemic to Ecuador. Nymphargus dajomesae was described in 2026, and named afted Neisi Dájomes, an Ecuadorian weightlifter.", where: "Endemic to Ecuador" },
  { year: 2026, group: "Amphibians", article: "Amolops guangzhouensis", scientific: "Amolops guangzhouensis", said: "Amolops guangzhouensis, the Guangzhou torrent frog, is a species of frog in the family Ranidae. It is endemic to Conghua in Guangzhou Province. The species was formally described in 2026 based on specimens collected from Guangzhou and Huizhou. The name was named after the province of Guangzhou, where it mostly founded.", where: "Endemic to Conghua in Guangzhou Province" },
  { year: 2026, group: "Amphibians", article: "Ameerega kuriinti", scientific: "Ameerega kuriinti", said: "Ameerega kuriinti, known commonly as Inti poison frog, is a species of poison dart frog in the family Dendrobatidae. It is endemic to Peru and occurs in the Department of San Martín. The species was formally described in 2026 by Geralds, Twomey, Deutsch, Chávez and Brown.", where: "Endemic to Peru and occurs in the Department of San Martín" },
  { year: 2026, group: "Animals", article: "Phrynus abstrusus", scientific: "Phrynus abstrusus", said: "Phrynus abstrusus is a troglophilous species of amblypygid from the southern United States. It was previously considered to be a population of Phrynus operculatus. P. abstrusus differs from most other species in its genus in lacking most pigment, with a translucent cuticle making some internal organs visible within the opisthosoma. In addition to pigmentation, it can be separated from P. operculatus by the morphology of the spines on their raptorial pedipalps, and by the anatomy of the female gonopods." },
  { year: 2026, group: "Animals", article: "Southeastern gentoo penguin", scientific: "Pygoscelis kerguelensis", said: "The southeastern gentoo penguin (Pygoscelis kerguelensis) is a species of penguin in the genus Pygoscelis. This species is endemic to the Kerguelen Islands in the southern Indian Ocean and is also believed to inhabit nearby Heard Island. Previously considered part of the gentoo penguin species (Pygoscelis papua), P. kerguelensis was formally identified and described as a distinct species in 2026 based on an integrated genomic analysis.", where: "Endemic to the Kerguelen Islands in the southern Indian Ocean" },
  { year: 2026, group: "Animals", article: "Sarax kosulici", scientific: "Sarax kosulici", said: "Sarax kosulici is a species of whipspider in the family Charinidae. It is known only from the island of Ko Pha Ngan in Thailand. The specific epithet, kosulici, is in honor of the collector of the specimens, Dr. Ondřej Košulič. It was described in 2026.", where: "Known only from the island of Ko Pha Ngan in Thailand" },
  { year: 2026, group: "Animals", article: "Rhopalomeris dinghushan", scientific: "Rhopalomeris dinghushan", said: "Rhopalomeris dinghushan is a species of pill millipede that belongs to the family Glomeridae. The species was named after the locality the species was discovered in, the Dinghu Mountains located in Guangdong, Southern China." },
  { year: 2026, group: "Archaea", article: "Nerearchaeum marumarumayae", scientific: "Nerearchaeum marumarumayae", said: "Nerearchaeum marumarumayae is a species of non-eukaryotic archaeon described in 2026, and a member of the taxonomic family Promethearchaeaceae. The species has a symbiotic relationship with another microorganism, the bacterium Stromatodesulfovibrio nilemahensis." },
  { year: 2026, group: "Beetles", article: "Deltochilum pseudoabdominale", scientific: "Deltochilum pseudoabdominale", said: "Deltochilum pseudoabdominale is a species of beetle of the family Scarabaeidae. It is found in Colombia (Arauca, Norte de Santander) and Venezuela (Lara, Mérida y Táchira), where it inhabits forests, conserved secondary forests, rainforests, and Podocarpus forests.", where: "Found in Colombia" },
  { year: 2026, group: "Beetles", article: "Deltochilum altiventris", scientific: "Deltochilum altiventris", said: "Deltochilum altiventris is a species of beetle of the family Scarabaeidae. It is found in Colombia (Cundinamarca, Arauca, Boyacá, Casanare, Meta), where it inhabits forests, sub-montane and montane forests, as well as primary and secondary forests.", where: "Found in Colombia" },
  { year: 2026, group: "Birds", article: "Tokara leaf warbler", scientific: "Phylloscopus tokaraensis", said: "The Tokara leaf warbler (Phylloscopus tokaraensis) is a species of leaf warbler from the Tokara Islands of Japan. There are two populations of the species on the islands of Izu and Tokara. The species is closely related to the Ijima's leaf warbler (Phylloscopus ijimae), they diverged from a common ancestor 3.2 million years ago. They are visually very similar but have noticeably different songs, as well as genetic differences. In the past, the birds used to be considered as a population of Ijima's leaf warbler." },
  { year: 2026, group: "Birds", article: "Cheerful fantail", scientific: "Rhipidura laguceria", said: "The cheerful fantail (Rhipidura laguceria) is a species of bird in the family Rhipiduridae. This species is one of 61 in the genus Rhipidura. It is endemic to the Babar Islands in the Banda Sea. It was described in 2026.", where: "Endemic to the Babar Islands in the Banda Sea" },
  { year: 2026, group: "Butterflies", article: "Colobura cryptica", scientific: "Colobura cryptica", said: "Colobura cryptica is a nymphalid butterfly described in 2026 within the Neotropical genus Colobura Billberg, 1820. It had long been confused with its close relative Colobura annulata due to subtly overlapping adult morphology, and was formally recognized only after integrative taxonomic analyses combining morphology, genomics, and life history data revealed it to be a genetically and ecologically distinct lineage." },
  { year: 2026, group: "Butterflies", article: "Euthalia zubeengargi", scientific: "Euthalia zubeengargi", said: "Euthalia zubeengargi, the Basar duke, is a species of butterfly in the family Nymphalidae, subfamily Limenitidinae. It was discovered by Roshan Upadhaya and Kalesh Sadasivan in the eastern Himalayan region of Arunachal Pradesh. The species is named in honor of Assamese singer and cultural icon Zubeen Garg." },
  { year: 2026, group: "Butterflies", article: "Aegiale occidentalis", scientific: "Aegiale occidentalis", said: "Aegiale occidentalis, the western tequila giant skipper, is a species of skipper butterfly in the subfamily Hesperiinae of the family Hesperiidae. It was described in 2026 by KC, McGuire, Willmott, Sapkota, and Shirey, making it a newly recognized species within the genus Aegiale." },
  { year: 2026, group: "Butterflies", article: "Rapala laximae", scientific: "Rapala laximae", said: "Rapala laximae is a species of butterfly in the family Lycaenidae. It is known only from Taw Maw in Kachin State, Myanmar, where the two known specimens were collected in April 1963. It was described in 2026, and the name \"narrow-banded flash\" has been proposed for it.", where: "Known only from Taw Maw in Kachin State, Myanmar" },
  { year: 2026, group: "Crustaceans", article: "Bathynomus apothecarius", scientific: "Bathynomus apothecarius", said: "Bathynomus apothecarius is a species of giant isopod found in the Western Atlantic Ocean (The Bahamas, Tongue of the Ocean). Bathynomus apothecarius was described in 2026, following other giant isopods described in the preceding decade: B. maxeyorum in 2016, B. raksasa in 2020, B. yucatanensis in 2022, and B. vaderi in 2025. These new discoveries suggest that the species diversity of giant isopods has been underestimated due to misidentifications. Bathynomus apothecarius is most closely related to B. maxeyorum.", where: "Found in the Western Atlantic Ocean" },
  { year: 2026, group: "Crustaceans", article: "Laureola volamuca", scientific: "Laureola volamuca", said: "Laureola volamuca is a species of isopods of the family Armadillidae that lives in China. The type specimen for this species was collected from Hainan Island. This species was described in 2026 by Zili Zong, Yutao Wang, Chao Jiang and Weichun Li.", where: "Lives in China" },
  { year: 2026, group: "Echinoderms", article: "Astroceramus pernachus", scientific: "Astroceramus pernachus", said: "Astroceramus pernachus is a species of deep sea starfish in the family of Goniasteridae. It was first described by Christopher L. Mah in 2026 from specimens collected off New Caledonia in the southwestern Pacific Ocean. The species name pernachus is derived from the pernach, a type of flanged mace." },
  { year: 2026, group: "Echinoderms", article: "Astroceramus cyclus", scientific: "Astroceramus cyclus", said: "Astroceramus cyclus is a species of deep-sea starfish in the family of Goniasteridae. It was first described by Christopher L. Mah in 2026 from specimens collected off New Caledonia. The species belongs to the genus Astroceramus, a group of deep-sea sea stars found in Pacific ocean.", where: "Found in Pacific ocean" },
  { year: 2026, group: "Echinoderms", article: "Asterodiscides conulus", scientific: "Asterodiscides conulus", said: "Asterodiscides conulus is a species of starfish in the family of Asterodiscididae. It was first described in 2026 from specimens collected at Ashmore Reef Marine Park, Western Australia. The species epithet conulus is derived from the Latin for cone." },
  { year: 2026, group: "Fish", article: "Helmethead sea Muppet", scientific: "Australyichthys aegis", said: "The helmethead sea Muppet (Australyichthys aegis) is a species of ray-finned fish in the sea Muppet genus Australyichthys (family Syngnathidae). Like other members of this genus, it has a superficially seahorse-like morphology, a result of convergent evolution of Australyichthys species on members of the genus Hippocampus. It is known from a single specimen incidentally collected by dredging activity off the coast of South Australia.", where: "Known from a single specimen incidentally collected" },
  { year: 2026, group: "Fish", article: "Hemiscyllium dudgeonae", scientific: "Hemiscyllium dudgeonae", said: "Hemiscyllium dudgeonae, also known as kadedekedewa or Dudgeon's walking shark, is a species of carpet shark that belongs to the family Hemiscylliidae (bamboo shark). This species is endemic to southeastern Papua New Guinea. The local name for the shark, kadedekedewa, loosely translates to \"dog shark\" or \"lazy shark\". The species' formal name is after the researcher who discovered it, Christine Dudgeon from the University of the Sunshine Coast located in Queensland, Australia.", where: "Endemic to southeastern Papua New Guinea" },
  { year: 2026, group: "Fish", article: "Magnischistura", scientific: "Magnischistura", said: "Magnischistura is a monospecific genus of freshwater ray-finned fish belonging to the family Nemacheilidae, the stone loaches. The only species in the genus is Magnischistura khaokrajom. This taxon was first formally described in 2026 with its type locality given as Huay Thong An, Mae Klong River basin, Suan Phueng District, Ratchaburi Province, Thailand at 13.54732N, 99.20394E from an elevation of 650 m (2,130 ft)." },
  { year: 2026, group: "Fish", article: "Demon cavefish", scientific: "Demogorgonichthys arcanus", said: "The demon cavefish (Demogorgonichthys arcanus) is a species of blind cavefish in the family Amblyopsidae. It is the only known species in the genus Demogorgonichthys and is known only from Bobcat Cave and its associated aquifer at Redstone Arsenal in northern Alabama, United States. The genus and species were formally described in 2026. The species inhabits the same cave pools as the southern cavefish (Typhlichthys subterraneus), although genetic analyses indicate that the two species are not closely related.", where: "Known only from Bobcat Cave and its associated aquifer at Redstone Arsenal in northern Alabama, United States" },
  { year: 2026, group: "Fish", article: "Musashi ninespine stickleback", scientific: "Pungitius nakamurai", said: "The Musashi ninespine stickleback (Pungitius nakamurai) is a species of fish in the stickleback genus Pungitius. Endemic to Japan, reported in 1963 and named in 2026. It occurs only in the Motoara River in Kumagaya, Saitama Prefecture (old Musashi Province). It is the prefectural fish, its habitat has been designated a prefectural natural monument, and a main belt asteroid, the minor planet 10776 Musashitomiyo, has been named in its honour.", where: "Endemic to Japan, reported in 1963 and named in 2026" },
  { year: 2026, group: "Fish", article: "Pterobunocephalus carvalhoi", scientific: "Pterobunocephalus carvalhoi", said: "Pterobunocephalus carvalhoi is a species of siluriform fish that belongs to the family Aspredinidae. It inhabits the upper Amazonian basin of Ecuador in the Napo, Pastaza, and Putumayo rivers. It has large eyes. The specific name \"carvalhoi\" is in honor to the Brazilian ichthyologist Tiago Pinto Carvalho for his far-reaching contributions to the study of fish species in the Neotropical realm and on particular the taxonomy and systematics of the family Aspredinidae.", where: "Inhabits the upper Amazonian basin of Ecuador in the Napo, Pastaza, and Putumayo rivers" },
  { year: 2026, group: "Gastropods", article: "Thecacera sesama", scientific: "Thecacera sesama", said: "Thecacera sesama is a species of nudibranch sea slug belonging to the family Polyceridae. It is native to northeastern Taiwan. Thecacera sesama is a specialized predator of bryozoans based on recording of this species before collection. Phylogenetic analysis of Thecacera sesama show that it is most closely related to Thecacera picta.", where: "Native to northeastern Taiwan" },
  { year: 2026, group: "Insects", article: "Pseudagrion crenatum", scientific: "Pseudagrion crenatum", said: "Pseudagrion crenatum is a species of damselfly in the family Coenagrionidae. In Australia this species is commonly known as a blue riverdamsel. The species occurs in northern and eastern Australia, Indonesian West Papua and Papua New Guinea. For many years Australian specimens of this species were treated as Pseudagrion microcephalum, however a 2026 revision of the Pseudagrion microcephalum complex recognised the Australian and Papuan populations as a distinct species, Pseudagrion crenatum.", where: "Occurs in northern and eastern Australia, Indonesian West Papua and Papua New Guinea" },
  { year: 2026, group: "Insects", article: "Dolichopoda balrogi", scientific: "Dolichopoda balrogi", said: "Dolichopoda balrogi is a species of cave cricket identified in a tunnel in the Greek island of Kastellorizo in 2026. It was formally described as species of the genus Dolichopoda by Greek researchers in a paper published by the Journal of Orthoptera Research based on morphological data and DNA Barcoding." },
  { year: 2026, group: "Insects", article: "Limnogonus macroconfusus", scientific: "Limnogonus macroconfusus", said: "Limnogonus macroconfusus is a species of water strider in the family Gerridae. It is found from southern southern Texas in the United States south throughout Mexico, Central America, and the Greater Antilles. It was named for being larger than and historically confused with L. franciscanus." },
  { year: 2026, group: "Mammals", article: "Likweli", scientific: "Colobus congoensis", said: "The likweli (Colobus congoensis) is a species of Old World monkey in the colobine genus Colobus. It is endemic to a small area of lowland rainforest between the Lomami River and the Lilo River in east-central Democratic Republic of the Congo (DRC), most of which lies within Lomami National Park. Formally described in 2026, it is the seventh recognised species of Colobus and the fifth new species of African monkey to be described in the previous 75 years." },
  { year: 2026, group: "Mammals", article: "Tilcayo", scientific: "Leopardus tilcayo", said: "The tilcayo (Leopardus tilcayo; til-KYE-oh; Spanish pronunciation: [tilˈkaʝo] ), or tilcayo tiger cat, is a species of small wild cat in the genus Leopardus native to Bolivia. Identified through a genetic study of tiger cats published in September 2026, the tilcayo is the first extant cat species formally described since 1923. The tilcayo was already known to local communities under that name.", where: "Native to Bolivia" },
  { year: 2026, group: "Molluscs", article: "Ferreiraella populi", scientific: "Ferreiraella populi", said: "Ferreiraella populi is a species of chiton, which is a type of marine polyplacophoran mollusc distinguished by eight articulating shell plates and bodies that are flattened dorsoventrally. Chitons live in a variety of environments, from intertidal zones to deep-sea areas. F. populi is a member of the Ferreiraella genus, of which there are ten members and two subspecies, including F. populi. Ferreiraella is the only genus in the family Ferreiraellidae. The Family and genus are endemic to sunken wood.", where: "Endemic to sunken wood" },
  { year: 2026, group: "Molluscs", article: "Microeledone galapagensis", scientific: "Microeledone galapagensis", said: "Microeledone galapagensis is a species of small octopus. In 2015, the holotype was discovered off the coast of Darwin Island in the Galápagos region of the Pacific 1,773 m (5,817 ft) below the surface. In May 2026, researchers from the Charles Darwin Foundation determined the specimen was a new species.", where: "Discovered off the coast of Darwin Island in the Galápagos region of the Pacific 1,773 m" },
  { year: 2026, group: "Moths", article: "Pyralis papaleonei", scientific: "Pyralis papaleonei", said: "Pyralis papaleonei is a species of moth that belongs to the family Pyralidae. It is endemic to the White Mountains located on the island of Crete in Greece. It is closely related to other species found in the eastern Mediterranean region being most closely related to Pyralis kacheticalis and Pyralis regalis. This species was named in honor of Pope Leo XIV who is currently the head of the Catholic Church. The species named \"papaleonei\" is derived from the Latin word for Pope Leo, \"Papa Leone\".", where: "Endemic to the White Mountains located on the island of Crete in Greece" },
  { year: 2026, group: "Plants", article: "Trichosanthes metamorpha", scientific: "Trichosanthes metamorpha", said: "Trichosanthes metamorpha is a dioecious perennial climber in the gourd family (Cucurbitaceae). It was described in 2026 from Yangshuo County, Guilin, Guangxi, China, and is placed in Trichosanthes sect. Involucraria. It was found in 2024 by the first author, then a 16-year-old enthusiast of Cucurbitaceae, during fieldwork in Yangshuo. The epithet refers to the stable difference between basal and apical leaves. It is distinguished from the similar T. dunniana and T.", where: "Found in 2024" },
  { year: 2026, group: "Plants", article: "Linaria almadensis", scientific: "Linaria almadensis", said: "Linaria almadensis is a species of toadflax in the plantain family Plantaginaceae, endemic to Portugal, specifically the coastal cliffs of Almada, (from where the species name comes) south of Lisbon. First described in 2026 by João Farminhão, it inhabits a very restricted area spanning only the sandy walls close to carbonate rocks in the cliffs pointed to the Tagus river with samples collected from rocks close to the Cristo Rei monument.", where: "Endemic to Portugal, specifically the coastal cliffs of Almada," },
  { year: 2026, group: "Plants", article: "Anaphalis sahyadrica", scientific: "Anaphalis sahyadrica", said: "Anaphalis sahyadrica is a species of flowering plant in the family Asteraceae. It is endemic to the northern Western Ghats of India, first described in 2026. It found in high altitude grassland and rocky plateau habitats, from 2,100 to 3,000 m (6,900 to 9,800 ft). The name sahyadrica refers to Sahayadri, the local name for the Western Ghats in Malayalam.", where: "Endemic to the northern Western Ghats of India, first described in 2026" },
  { year: 2026, group: "Plants", article: "Arisaema siahaense", scientific: "Arisaema siahaense", said: "Arisaema siahaense is a species of flowering plant in the family Araceae. It is endemic to northeastern India and was discovered in the state of Mizoram. The species was formally identified and named in 2026 based on distinctive morphological characteristics.", where: "Endemic to northeastern India" },
  { year: 2026, group: "Plants", article: "Melanoseris pendryi", scientific: "Melanoseris pendryi", said: "Melanoseris pendryi is a species of flowering plant in the family Asteraceae. It was discovered in the alpine grasslands of the Indian state of Sikkim in the Himalayas at elevations above 4,000 m (13,000 ft) and first described in 2026.", where: "Discovered in the alpine grasslands of the Indian state of Sikkim in the Himalayas at elevations above 4,000 m" },
  { year: 2026, group: "Reptiles", article: "Varanus phosphoros", scientific: "Varanus phosphoros", said: "Varanus phosphoros, known commonly as the yellow-headed rock monitor, is a species of small-bodied, rock-adapted monitor lizard endemic to Far North Queensland. It was formally described in 2026 along with its close relatives Varanus iridis and Varanus umbra. The three species form part of a clade which diverged from other Odatrian monitor lizards around 7 million years ago.", where: "Endemic to Far North Queensland" },
  { year: 2026, group: "Reptiles", article: "Varanus umbra", scientific: "Varanus umbra", said: "Varanus umbra, known commonly as the orange-headed rock monitor, is a species of small-bodied, rock-adapted monitor lizard endemic to Far North Queensland. It was formally described in 2026 along with its close relatives Varanus iridis and Varanus phosphoros. The three species form part of a clade which diverged from other Odatrian monitor lizards around 7 million years ago.", where: "Endemic to Far North Queensland" },
  { year: 2026, group: "Reptiles", article: "Varanus iridis", scientific: "Varanus iridis", said: "Varanus iridis, commonly known as the rainbow rock monitor, is a species of small-bodied, rock-adapted monitor lizard endemic to Far North Queensland. It was formally described in 2026 along with its close relatives Varanus phosphoros and Varanus umbra. The three species form part of a clade which diverged from other Odatrian monitor lizards around 7 million years ago.", where: "Endemic to Far North Queensland" },
  { year: 2026, group: "Reptiles", article: "Cyrtodactylus nebulicola", scientific: "Cyrtodactylus nebulicola", said: "Cyrtodactylus nebulicola is a species of gecko that belongs to the subfamily Gekkoninae. It is native to the eastern Himalayan region of India. It is a medium-sized species that can reach to a maximum snout-to-vent length of 75.1 millimeters.", where: "Native to the eastern Himalayan region of India" },
  { year: 2026, group: "Reptiles", article: "Eublepharis jhuma", scientific: "Eublepharis jhuma", said: "Eublepharis jhuma is a species of leopard gecko in the family Eublepharidae. It was discovered in the Kaimur Hills near the Kaimur Wildlife Sanctuary in Bihar, India. It was the seventh species in the family Eublepharidae to be described.", where: "Discovered in the Kaimur Hills near the Kaimur Wildlife Sanctuary in Bihar, India" },
  { year: 2026, group: "Reptiles", article: "Dasypeltis albigularis", scientific: "Dasypeltis albigularis", said: "Dasypeltis albigularis, commonly known as the white-throated egg-eating snake or white-throated egg-eater, is a species of non-venomous snake in the family Colubridae. The species is endemic to the Harenna Forest in southern Ethiopia.", where: "Endemic to the Harenna Forest in southern Ethiopia" },
  { year: 2025, group: "Amphibians", article: "Western desert tree frog", scientific: "Colleeneremia larisonans", said: "The western desert tree frog (Colleeneremia larisonans) is a species of tree frog in the family Pelodryadidae, endemic to the arid and coastal regions of central western Australia. It is primarily found in dry habitats, though in the most arid parts of its distribution, it is restricted to ranges or larger rivers. It breeds in mostly still water, mainly flooded areas and ponds.", where: "Endemic to the arid and coastal regions of central western Australia" },
  { year: 2025, group: "Amphibians", article: "Brachycephalus nanicus", scientific: "Brachycephalus nanicus", said: "Brachycephalus nanicus is a species of small frog in the family Brachycephalidae endemic to the Atlantic Forest of Brazil. It is one of more than 40 named species within the genus Brachycephalus, and is most closely related to Brachycephalus puri. B. nanicus is a very small species; adult males range from 6.9–9.0 millimetres (0.27–0.35 in) (SVL), while females are slightly larger, at 9.2–9.6 mm (0.36–0.38 in).", where: "Endemic to the Atlantic Forest of Brazil" },
  { year: 2025, group: "Amphibians", article: "Ruddy tree frog", scientific: "Colleeneremia pyrina", said: "The ruddy tree frog (Colleeneremia pyrina) is a species of tree frog in the family Pelodryadidae, endemic to eastern Australia. It is primarily found in human-disturbed habitats, mostly heard calling in suburban and rural areas in eastern Australia. It breeds in still waterbodies, primarily small to large ponds and flooded areas. The ruddy tree frog is highly variable in colour, ranging from light grey (especially at daytime) to brown to brick red.", where: "Endemic to eastern Australia" },
  { year: 2025, group: "Amphibians", article: "Leptobrachium aryatium", scientific: "Leptobrachium aryatium", said: "Leptobrachium aryatium is a species of toad in the genus Leptobrachium which was described from Garbhanga Reserve Forest, Assam, India. The specific name 'arya' was given to honor the college where the author worked and specimen is kept. It is a medium-sized frog with adult SVL is 49.0–55.4 mm for males and 53.2–61.65 mm for females. Phylogenetic analyses showed that Leptobrachium aryatium is sister lineage to the clade comprising L. sylheticum and L. smithi", where: "Described from Garbhanga Reserve Forest, Assam, India" },
  { year: 2025, group: "Amphibians", article: "Ranitomeya aquamarina", scientific: "Ranitomeya aquamarina", said: "Ranitomeya aquamarina, also known as the metallic poison frog, is a species of small frog in the family Dendrobatidae endemic to the Juruá River basin of Brazil. It is one of at least 18 species named in the genus Ranitomeya and is uniquely characterized by its bright blue to yellow-green and black body and metallic spotted legs.", where: "Endemic to the Juruá River basin of Brazil" },
  { year: 2025, group: "Amphibians", article: "Amolops shillong", scientific: "Amolops shillong", said: "Amolops shillong is a species of cascade-dwelling frog of genus, Amolops. A. shillong is found within the urban landscape of Shillong, the capital city of Meghalaya in Northeast India. This species is differentiated from other species based on a distinct set of morphological characters and its isolated geographical space." },
  { year: 2025, group: "Animals", article: "Physalia minuta", scientific: "Physalia minuta", said: "Physalia minuta, also called little bluebottle, is a species of physalid siphonophore native to the oceanic waters around the Southern Hemisphere. Its longer pneumatophore distinguishes it from other species of its genus. Though many systematists have treated its genus, Physalia, as containing a single species, Physalia physalis, the Portuguese man o' war, recent studies, morphological and genetic, have proven there to be upwards of four to five species in the genus, among them being Physalia minuta.", where: "Native to the oceanic waters around the Southern Hemisphere" },
  { year: 2025, group: "Animals", article: "Diplolaimelloides woaabi", scientific: "Diplolaimelloides woaabi", said: "Diplolaimelloides woaabi is a species of free-living, halophilic nematode within the family Monhysteridae. Described in 2025, it is the first nematode species identified as endemic to the Great Salt Lake in the U.S. state of Utah. As an extremophile, it is one of only three animal taxa known to inhabit the lake's hypersaline waters, alongside brine shrimp (Artemia) and brine flies (Ephydra).", where: "Endemic to the Great Salt Lake in the U" },
  { year: 2025, group: "Animals", article: "Androctonus ammoneus", scientific: "Androctonus ammoneus", said: "Androctonus ammoneus is a species of fat-tailed scorpion. It was formally described in 2025. These scorpions are found throughout the Middle Eastern country of Jordan, but are particularly common in the eastern deserts. All Androctonus species have powerful neurotoxic venom, but this species in particular has a tendency to seek human-adjacent habitat with commensurate increased risk of human injury. The specific name comes from the ancient Levantine kingdom of Ammon. Specimens of A." },
  { year: 2025, group: "Animals", article: "Iridogorgia chewbacca", scientific: "Iridogorgia chewbacca", said: "Iridogorgia chewbacca is a species of deep-sea bamboo coral in the family Chrysogorgiidae. Named after the Star Wars character Chewbacca due to its long, flexible, \"hairy\" branches, the species was formally described in 2025. It inhabits rocky seafloors in the tropical western Pacific Ocean at depths exceeding 400 meters, where it forms solitary colonies up to 1.2 meters tall.", where: "Inhabits rocky seafloors in the tropical western Pacific Ocean at depths exceeding 400 meters" },
  { year: 2025, group: "Animals", article: "Charinus santandereanus", scientific: "Charinus santandereanus", said: "Charinus santandereanus is a species of whipspider found in Colombia. The type specimens of this species, two females, were collected from the aphotic zone of a wet cave in the Santander Department, Colombia. The species is known only from the cave in which the type specimens were found.", where: "Found in Colombia" },
  { year: 2025, group: "Animals", article: "Marphysa tompaulingi", scientific: "Marphysa tompaulingi", said: "Marphysa tompaulingi is a species of annelid worm in the family Eunicidae. It is endemic to the islands of the Northern Territory, Australia, where it has currently only been identified from the mid-channel of the Ludmilla Creek, East Point Reserve, Darwin.", where: "Endemic to the islands of the Northern Territory, Australia" },
  { year: 2025, group: "Archaea", article: "Sukunaarchaeum", scientific: "Sukunaarchaeum mirabile", said: "\"Candidatus Sukunaarchaeum mirabile\" (provisional name) is a species of archaea of which only the DNA is known, but which already presents several particularities: it is a holoparasite of the dinoflagellate Citharistes regius. Its DNA, the smallest known for an archaeon, codes only for proteins necessary for reproduction." },
  { year: 2025, group: "Bacteria", article: "Niallia tiangongensis", scientific: "Niallia tiangongensis", said: "Niallia tiangongensis is a Gram-positive, aerobic, spore-forming, rod-shaped bacterium belonging to the genus Niallia within the family Bacillaceae. It was first isolated from surface samples collected aboard the Tiangong space station during China's Shenzhou 15 mission in May 2023. The species was formally described in 2025 following genomic and phenotypic analyses." },
  { year: 2025, group: "Beetles", article: "Lamellipalpodes kurumba", scientific: "Lamellipalpodes kurumba", said: "Lamellipalpodes kurumba is a rare, non-luminous species of firefly discovered in the Nilgiri Hills of the Western Ghats in Tamil Nadu, India. The Western Ghats are internationally recognized as one of the world's major biodiversity hotspots, characterized by high levels of species richness and endemism. Lamellipalpodes is a genus of non-luminous fireflies within the family Lampyridae, characterized by distinctly broadened terminal labial and maxillary palpomeres.", where: "Discovered in the Nilgiri Hills of the Western Ghats in Tamil Nadu, India" },
  { year: 2025, group: "Beetles", article: "Osphya flavomarginata", scientific: "Osphya flavomarginata", said: "Osphya flavomarginata is a species of beetle of the Melandryidae family. This species is only known from the type locality Tiechang Village in Yunlong County in China. Adults reach a length of about 7.7 mm. The antennae are bicolored, with the apical four segments yellow. The pronotum is basally yellow and there is a yellow region along the posterior margin and the basal half of the lateral margins. The elytra are metallic green with golden recumbent setae.", where: "Known from the type locality Tiechang Village in Yunlong County in China" },
  { year: 2025, group: "Beetles", article: "Scaphisoma infinitum", scientific: "Scaphisoma infinitum", said: "Scaphisoma infinitum is a species of beetle of the Staphylinidae family. This species is found in south-eastern Brazil (Minas Gerais). Adults reach a length of about 1.09–1.36 mm and have a dark brown body. Adults have been collected from undetermined resupinate and/or crust fungi. A few specimens where collected from a small decomposing log with Ceratiomyxa fruticulosa.", where: "Found in south-eastern Brazil" },
  { year: 2025, group: "Beetles", article: "Litargus arjanbasui", scientific: "Litargus arjanbasui", said: "Litargus arjanbasui is a species of hairy fungus beetles of family Mycetophagidae. Currently known from West Bengal and Meghalaya states of India. The species has been named in honour of nature conservationist Mr. Arjan Basu Roy, Secretary of the Nature Mates Nature Club in West Bengal, India, for his contribution in the field of butterfly conservation and ecotourism.", where: "Known from West Bengal and Meghalaya states of India" },
  { year: 2025, group: "Beetles", article: "Osphya clavata", scientific: "Osphya clavata", said: "Osphya clavata is a species of beetle of the Melandryidae family. This species is only known from the type locality Xima in Yingjiang County in China. Adults reach a length of about 4.7 mm. The dorsum is black without metallic hue and elytra have thickened recumbent setae forming a whitish pattern. The antennae, mouthparts, protibiae, and tarsi are all yellow.", where: "Known from the type locality Xima in Yingjiang County in China" },
  { year: 2025, group: "Beetles", article: "Poecilomorpha pseudocribricollis", scientific: "Poecilomorpha pseudocribricollis", said: "Poecilomorpha pseudocribricollis is a species of beetle in the family Megalopodidae. This species is found in the Democratic Republic of the Congo. Adults reach a length of about 6.5 mm. The head, antennae, pronotum and elytral basal thirds are orange, while the elytral apical two-thirds is iridescent black-violet. The mandibles, legs and abdomen are brown.", where: "Found in the Democratic Republic of the Congo" },
  { year: 2025, group: "Birds", article: "Hooded jewel-babbler", scientific: "Ptilorrhoa urrissia", said: "The hooded jewel-babbler (Ptilorrhoa urrissia) is a species of bird in the family Cinclosomatidae, endemic to the forested karst of the Southern Fold Mountains in Papua New Guinea. It is one of five named species in the genus Ptilorrhoa (jewel-babblers), currently known only from camera trap photograph sequences obtained between 2017 and 2024.", where: "Endemic to the forested karst of the Southern Fold Mountains in Papua New Guinea" },
  { year: 2025, group: "Butterflies", article: "Satyrium curiosolus", scientific: "Satyrium curiosolus", said: "Satyrium curiosolus, also known as curiously isolated hairstreak, is a species of butterfly in the family Lycaenidae that was first described in 2025. It is an isolated species found only on Blakiston Fan in Waterton Lakes National Park, Alberta, Canada. Long considered an isolated population of the half-moon hairstreak, genomic and ecological studies revealed it to be a distinct species that has likely been separated from its closest relatives for more than 40,000 years.", where: "Found only on Blakiston Fan in Waterton Lakes National Park, Alberta, Canada" },
  { year: 2025, group: "Butterflies", article: "Zographetus mathewi", scientific: "Zographetus mathewi", said: "Zographetus mathewi, also known as the Sahyadri spotted flitter, is a butterfly in the family Hesperiidae. It is found in Kerala in India. It was described by Kalesh Sadasivan and others in 2025. This species is monotypic.", where: "Found in Kerala in India" },
  { year: 2025, group: "Cephalopods", article: "Cirroteuthis kirrilyae", scientific: "Cirroteuthis kirrilyae", said: "Cirroteuthis kirrilyae is a species of cirrate octopus in family Cirroteuthidae, previously confused with the closely related Cirroteuthis muelleri. The species was described by T.J. Verhoeff and Steve O'Shea. The species is known from specimens collected around Australia, New Zealand, and New Caledonia, and is a pelagic or benthopelagic species known from a depth range of 1497-2581 m.", where: "Known from specimens collected around Australia, New Zealand, and New Caledonia" },
  { year: 2025, group: "Cephalopods", article: "Grimpoteuthis feitiana", scientific: "Grimpoteuthis feitiana", said: "Grimpoteuthis feitiana is a small species of dumbo octopus from the Western Pacific known from a single specimen collected at the Caroline Seamount at a depth of 1,240 m (4,070 ft) in 2017; it was subsequently described as a new species in 2025. The specific name 'feitiana' references 'feitian', a goddess from the Chinese Mogao Cave Culture known for her graceful aerial dancing, resembling the way dumbo octopuses move underwater in their natural habitat.", where: "Known from a single specimen collected at the Caroline Seamount at a depth of 1,240 m" },
  { year: 2025, group: "Cephalopods", article: "Opisthoteuthis carnarvonensis", scientific: "Opisthoteuthis carnarvonensis", said: "Opisthoteuthis carnarvonensis, also known as the Carnarvon flapjack octopus, is a species of umbrella octopus in the family Opisthoteuthidae. The type specimen was collected by scientists during a CSIRO voyage, on the RV Investigator, in late 2022 at the Carnarvon Canyon Marine Park. The species was formally described in May 2025." },
  { year: 2025, group: "Crustaceans", article: "Ligidium schultzi", scientific: "Ligidium schultzi", said: "Ligidium schultzi is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is known from the southern Blue Ridge Mountains of Georgia, North Carolina, South Carolina and Tennessee. The species name schultzi honors George Schultz for his contributions to knowledge of Ligidium in North America. Additionally, Schultz discovered and illustrated Ligidium schultzi in 1982 but incorrectly identified it as a variant of Ligidium elrodii.", where: "Found in the United States" },
  { year: 2025, group: "Crustaceans", article: "Ligidium whiteoak", scientific: "Ligidium whiteoak", said: "Ligidium whiteoak is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is only known from a single location in Blount County, Tennessee. The species name whiteoak refers to Whiteoak Sink, a trail within Great Smoky Mountains National Park, where the species was first discovered. Its habitat consists of moist leaf litter in deciduous forest.", where: "Found in the United States" },
  { year: 2025, group: "Crustaceans", article: "Ligidium pacolet", scientific: "Ligidium pacolet", said: "Ligidium pacolet is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is only known from a single location in Polk County, North Carolina. The species name pacolet refers to the North Pacolet River, near where the only specimens of the species have so far been collected. Its habitat consists of moist leaf litter in deciduous forest.", where: "Found in the United States" },
  { year: 2025, group: "Crustaceans", article: "Ligidium gadalutsi", scientific: "Ligidium gadalutsi", said: "Ligidium gadalutsi is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is known from three locations: Haywood County, North Carolina and Sevier County, Tennessee (both within Great Smoky Mountains National Park), and Clay County, North Carolina (within Nantahala National Forest). The species name gadalutsi comes from the Cherokee word that originated the English \"Cataloochee\", in reference to the type locality, Big Cataloochee Mountain.", where: "Found in the United States" },
  { year: 2025, group: "Crustaceans", article: "Ligidium nantahala", scientific: "Ligidium nantahala", said: "Ligidium nantahala is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is only known from a single location in Clay County, North Carolina. The species name nantahala refers to Nantahala National Forest, where the only specimens of Ligidium nantahala have so far been collected. Its habitat consists of broad-leaf forest leaf litter.", where: "Found in the United States" },
  { year: 2025, group: "Crustaceans", article: "Ligidium protuberans", scientific: "Ligidium protuberans", said: "Ligidium protuberans is a species of terrestrial isopod in the family Ligiidae, found in the United States. It is known from several locations in the southern Blue Ridge Mountains of North Carolina and South Carolina. The species name protuberans comes from Latin \"protubero\", meaning \"protuberance\", in reference to the species' characteristic projection on the male second pleopod endopodite.", where: "Found in the United States" },
  { year: 2025, group: "Fish", article: "Atlantic manta ray", scientific: "Mobula yarae", said: "The Atlantic manta ray (Mobula yarae) is a species of ray in the family Mobulidae. It is the third manta ray species to be named, following the giant oceanic manta ray (M. birostris) and reef manta ray (M. alfredi), and one of at least nine extant species in the genus Mobula. With a maximum estimated size (disc width) of 5–6 metres (16–20 ft), the Atlantic manta ray is also among the largest rays, alongside the two other mantas." },
  { year: 2025, group: "Fish", article: "Peckoltia amjikin", scientific: "Peckoltia amjikin", said: "Peckoltia amjikin is a species of freshwater ray-finned fish belonging to the family Loricariidae, the suckermouth armoured catfishes, and the subfamily Hypostominae, the suckermouth catfishes. This catfish was first formally described in 2025 with its type locality given as Bom Jesus do Tocantins, on the Tocantins River in the Brazilian state of Pará at 5°20'11.9\"S, 48°51'15.5\"W. This species reaches a standard length of 64.8 mm (2.55 in)." },
  { year: 2025, group: "Fish", article: "Sicklefin redhorse", scientific: "Moxostoma ugidatli", said: "The sicklefin redhorse (Moxostoma ugidatli) is a species of freshwater ray-finned fish in the genus Moxostoma. It is endemic to the southeastern United States, where it is known from a small section of the Appalachian Mountains in southwestern North Carolina and northern Georgia. Long known to the Cherokee people, it was only scientifically recognized as a distinct species in 1992, and only officially given a scientific name in 2025.", where: "Endemic to the southeastern United States" },
  { year: 2025, group: "Fish", article: "Mesonauta karipuna", scientific: "Mesonauta karipuna", said: "Mesonauta karipuna is a species of ray-finned fish belonging to the cichlid family (Cichlidae). The species' was first described in 2025 by Rianne Caroline de Oliveira, Ricardo Britzke, Claudio Oliveira & Weferson Júnio da Graça. A relatively new species of Mesonauta from the Amapá Grande River basin in northern Brazil. This species is distinguished from all its congeners by its coloration pattern and the shape of flank bars 3 to 7." },
  { year: 2025, group: "Fish", article: "Barbucca heokhuii", scientific: "Barbucca heokhuii", said: "Barbucca heokhuii is a miniature loach found in the Rungan watershed of Central Borneo. The largest known specimen has a length of 21.5 mm (0.85 in), making it the smallest known species of Barbucca. Its population has not been evaluated. It differentiates itself from other species in the Barbucca genus by having a smaller size, different patterns, an incomplete lateral line and more. It coexists with Barbucca diabolica.", where: "Found in the Rungan watershed of Central Borneo" },
  { year: 2025, group: "Fish", article: "Klapanunggal blind cave barb", scientific: "Barbodes klapanunggalensis", said: "Klapanunggal blind cave barb (Barbodes klapanunggalensis), known locally as wader buta, is a species of barb from the Klapanunggal karst area of Bogor Regency, West Java. It is a cavefish, being endemic to water bodies within the caves of the region; typical of cavefish (though not of Barbodes), B. klapanunggalensis is eyeless and unpigmented, and it can be distinguished from its congeners by multiple other features, including enlarged paired fins.", where: "Endemic to water bodies within the caves of the region" },
  { year: 2025, group: "Fungi", article: "Periglandula clandestina", scientific: "Periglandula clandestina", said: "Periglandula clandestina is a fungus of the genus Periglandula. It is symbiotic with the morning glory plant Ipomoea tricolor (the Mexican morning glory). Ipomoea tricolor seeds are hallucinogenic in humans due to the presence of naturally occurring lysergamides or ergot alkaloids like ergine (lysergic acid amide; LSA) and isoergine (isolysergic acid amide; iso-LSA)." },
  { year: 2025, group: "Fungi", article: "Chromosera loreleiae", scientific: "Chromosera loreleiae", said: "Chromosera loreleiae is a delicate multihued yellow-pink-lilac species of mushroom. Chromosera loreleia was newly described in 2025 as a western North American species. Western North American specimens had previously been assigned to Chromosera cyanophylla, before DNA studies found them to be genetically distinct. Chromosera lorelaiae, Chromosera cyanophylla, and Chromosera lilacifolia \"form a strongly supported clade.\" The specific name honors Lorelei L." },
  { year: 2025, group: "Gastropods", article: "Phyllidia ovata", scientific: "Phyllidia ovata", said: "Phyllidia ovata is a nudibranch species discovered by five women scientists from Germany, Indonesia, and Wales. The species' name comes from its unique egg-like oval shape, one of the most noticeable features of the nudibranch. The nudibranch's tubercules are vibrant and white with yellow tips. The nudibranch is medium-sized with its length reaching up to 5 cm (2 in). This species inhabits coral reefs in the Indo-Pacific region.", where: "Inhabits coral reefs in the Indo-Pacific region" },
  { year: 2025, group: "Insects", article: "Lyriothemis abrahami", scientific: "Lyriothemis abrahami", said: "Lyriothemis abrahami is a species of dragonfly in the family Libellulidae. It is found in Western Ghats of Southern India. This dragonfly was previously misidentified as L. flava. In contrast to L. flava, the new species is sexually dimorphic, with males can be easily distinguished based on the characteristic shape of the hamules. Females can be distinguished by their jet-black and yellow color with triangular yellow streaks on the dorsum of the abdomen.", where: "Found in Western Ghats of Southern India" },
  { year: 2025, group: "Insects", article: "Celastrina iryna", scientific: "Celastrina iryna", said: "Celastrina iryna, or Iryna's azure, is a butterfly species in the family Lycaenidae, named in honor of Iryna Zarutska, who was killed in 2025. Thought to be a hybrid species, the males differ from Celastrina neglecta by their absence of androconia and presence of elongated wing scales, while the females have a nearly immaculate white underside. The butterfly has been observed in South Carolina's Aiken, Barnwell, Dorchester, Jasper, and Orangeburg counties, as well as in Georgia, northern Florida and Mississippi." },
  { year: 2025, group: "Insects", article: "Ropalidia mabawa", scientific: "Ropalidia mabawa", said: "Ropalidia mabawa is an African species of paper wasp, described in 2025, based on a single collected specimen. It represents a special lineage in the African members of this genus, with several unique characteristics. These include apically darkened wing, entirely reddish body, short mesosoma, elongated T1, shallow punctures and striate propodeum. The general appearance resembles another Polistinae genus, Belonogaster." },
  { year: 2025, group: "Insects", article: "Acrophylla alta", scientific: "Acrophylla alta", said: "Acrophylla alta is a species of stick insect in the tribe Phasmatini described in 2025. Named the Highlands Giant Acrophylla, this species was found in the Atherton Tablelands: highland tropical forests of Queensland (Millaa Millaa is the type locality). The species was described by scientists Ross M. Coupland and Angus J. Emmott based on two female specimens.", where: "Found in the Atherton Tablelands: highland tropical forests of Queensland" },
  { year: 2025, group: "Insects", article: "Hylaeus paumako", scientific: "Hylaeus paumako", said: "Hylaeus paumako is a species of bee endemic to the Hawaiian island of Molokaʻi. It was discovered in a designated conservation and wilderness area in the ahupuaʻa of Mākolelau in 2024 and later described in 2025. The bee is notable as the only known bee species on the island where the males are completely black (Hylaeus are generally yellow-faced). H. paumako is the first new species of bee found on the island of Molokaʻi in over a century.", where: "Endemic to the Hawaiian island of Molokaʻi" },
  { year: 2025, group: "Insects", article: "Euphaea wayanadensis", scientific: "Euphaea wayanadensis", said: "Euphaea wayanadensis, the wayanad damselfly, is a species of damselfly in the family Euphaeidae. The species name wayanadensis is an adjectival toponym derived from the type locality in Wayanad District, Kerala, India. This species is endemic to the Western Ghats, known to occur only in the fast-flowing streams and riparian patches of Kerala, Wayanad district around Thirunelli. Other specimens were found in Kannur district, in Aaralam." },
  { year: 2025, group: "Lichens", article: "Polycauliona pancakeana", scientific: "Polycauliona pancakeana", said: "Polycauliona pancakeana is a rare species of saxicolous (rock-dwelling) crustose lichen in the family Teloschistaceae. It forms a continuous mat of tiny, pale orange-yellow granules on granite rock in deeply shaded, humid locations along mountain streams and canyons. Described in 2025 from the Indian Peaks Wilderness of Colorado, the species is known from only four individuals at three sites in the southern Rocky Mountains.", where: "Known from only four individuals at three sites in the southern Rocky Mountains" },
  { year: 2025, group: "Lichens", article: "Gyalolechia paradoxa", scientific: "Gyalolechia paradoxa", said: "Gyalolechia paradoxa is a species of lichen in the family Teloschistaceae. It was described as new to science in 2025 from collections made on Medny Island in the Commander Islands of the Russian Far East, where it grows on mosses and sometimes as a parasite on other lichens in mountain tundra. The species has an orange to orange-red body with dark rust-coloured fruiting structures, and is named for its unusual combination of traits that the authors of the species considered atypical for the genus." },
  { year: 2025, group: "Lichens", article: "Athallia subrotundispora", scientific: "Athallia subrotundispora", said: "Athallia subrotundispora is a species of crustose lichen in the family Teloschistaceae. It was described as new to science in 2025 from collections made in the Bering Island in the Commander Islands of the Russian Far East. The lichen has a thin, inconspicuous body but produces abundant orange fruiting structures, and is distinguished from related species by its unusually broad, almost spherical spores. It has been found growing on both rocks and driftwood in tundra and coastal habitats." },
  { year: 2025, group: "Lichens", article: "Gyalolechia orientoinsularis", scientific: "Gyalolechia orientoinsularis", said: "Gyalolechia orientoinsularis is a species of corticolous (bark-dwelling) crustose lichen in the family Teloschistaceae. It was described as new to science in 2025 from the Commander Islands in the Russian Far East, and has also been recorded from Sakhalin. The lichen has a thin yellow body with contrasting reddish-brown fruiting structures, and grows on the bark of shrubs and trees in coastal meadows and mountain slopes." },
  { year: 2025, group: "Lichens", article: "Filsoniana fabricola", scientific: "Filsoniana fabricola", said: "Filsoniana fabricola is a species of lichen-forming fungus in the family Teloschistaceae. Found in China, it was formally described as a new species in 2025. The type was collected in De-ching town (Lhasa, Tibet Autonomous Region), where it was found growing on the surface of old worn-out clothes found at the field ridge in the mountains. The species epithet, fabricola, refers to its unusual substrate.", where: "Found in China, it was formally described as a new species in 2025" },
  { year: 2025, group: "Lichens", article: "Pyrenula dalmatioides", scientific: "Pyrenula dalmatioides", said: "Pyrenula dalmatioides is a species of lichen in the family Pyrenulaceae which is endemic to New Zealand. It was first described in 2025 by Andrew J. Marshall, Dan Blanchon, Peter de Lange, and André Aptroot. Found in the northern North Island, the species lives almost exclusively in mangrove forests, and is an early coloniser species, displaced by different lichens over time.", where: "Endemic to New Zealand" },
  { year: 2025, group: "Mammals", article: "Fringe-eared Mindoro forest mouse", scientific: "Apomys crinitus", said: "The fringe-eared Mindoro forest mouse or long-haired Mindoro forest mouse (Apomys crinitus) is a species of rodent in the family Muridae, from the genus Apomys, in the subgenus Megapomys. It is found only in the island of Mindoro in the Philippines where was found at elevations between 140 and 880 m above sea level. Its natural habitat is deciduous karst forests.", where: "Found only in the island of Mindoro in the Philippines" },
  { year: 2025, group: "Mammals", article: "Veluz's Mindoro forest mouse", scientific: "Apomys veluzi", said: "The Veluz's forest mouse (Apomys veluzi) is a species of rodent in the family Muridae, from the genus Apomys, in the subgenus Megapomys. It is found only in the island of Mindoro in the Philippines where was found at elevations between 710 and 1,325 m above sea level. Its natural habitat is both lowland and montane forests. The species is characterized by its brown fur at the back, with bellies that are cream-colored, and a mask of dark-color fur in the face.. It has a head–body length of 129.1 mm.", where: "Found only in the island of Mindoro in the Philippines" },
  { year: 2025, group: "Mammals", article: "Small Mindoro forest mouse", scientific: "Apomys minor", said: "The small Mindoro forest mouse (Apomys minor) is a species of rodent in the family Muridae, from the genus Apomys, in the subgenus Megapomys. It is found only in the island of Mindoro in the Philippines where was found at elevations between 300 and 1,280 m above sea level. Its natural habitat secondary lowland forest with an open canopy. The species is characterized by its small size, brown fur at the back, and bellies that are pale brown. It has a head–body length of 122 mm.", where: "Found only in the island of Mindoro in the Philippines" },
  { year: 2025, group: "Mammals", article: "Hipposideros srilankaensis", scientific: "Hipposideros srilankaensis", said: "Hipposideros srilankaensis is a 2025 identified leaf-nosed bat species endemic to Sri Lanka. Previously classified under Hipposideros galeritus, it was reclassified based on morphological, genetic, and echolocation call analyses.", where: "Endemic to Sri Lanka" },
  { year: 2025, group: "Mammals", article: "Mustela mopbie", scientific: "Mustela mopbie", said: "Mustela mopbie is a species of weasel found in the Hengduan Mountains in Sichuan Province in southwestern China. It was first described in 2025. Compared to other Asian weasels, it has an unusually slim profile, with a shorter body and tail, a lighter frame, and a narrower head. This allows it to enter tight crevices and burrows to catch insects and small rodents. It also has a distinct coloration and fur pattern.", where: "Found in the Hengduan Mountains in Sichuan Province in southwestern China" },
  { year: 2025, group: "Mammals", article: "Himalayan long-tailed myotis", scientific: "Myotis himalaicus", said: "The Himalayan long-tailed myotis (Myotis himalaicus), is a species of bat in the family Vespertilionidae. It was formally described in 2025 from the high altitude Western Himalayas of Uttarakhand, India, based on museum specimens and live catches, echolocation call structure, and DNA evidence. The species belongs to the Myotis frater species complex." },
  { year: 2025, group: "Molluscs", article: "Delectopecten thermus", scientific: "Delectopecten thermus", said: "Delectopecten thermus is a species of marine bivalve mollusk in the family Pectinidae, the scallops. The holotype was collected at a depth of 962 m from the Higashi-Ensei vent field, in the northern Okinawa Trough off the coast of southern Japan. Among its congeners, D. thermus most resembles D. vancouverensis and D. gelatinosus, but differs in the notably unequal sizes of its anterior and posterior auricles, strongly curved anterior auricle of the left valve, and greater byssal notch angle. D." },
  { year: 2025, group: "Plants", article: "Nepenthes maagnawensis", scientific: "Nepenthes maagnawensis", said: "Nepenthes maagnawensis is a tropical pitcher plant endemic to the shrublands of the Kitanglad Mountain Range, Mindanao, Philippines. Specifically, it is known from Mt. Maagnaw in Lantapan, Bukidnon. Morphologically, N. maagnawensis closely resembles Nepenthes kitanglad. However, it differs by having terete stems, lamina with inconspicuous pinnate venation, aerial pitchers that are broadest in the upper third, and a triangular basal central appendage on the aerial pitcher lid. In contrast, N.", where: "Endemic to the shrublands of the Kitanglad Mountain Range, Mindanao, Philippines" },
  { year: 2025, group: "Plants", article: "Quercus salasiae", scientific: "Quercus salasiae", said: "Quercus salasiae is a species of oak. It is a tree native to the southern Mexican states of Chiapas, Guerrero, and Oaxaca. It grows in the Sierra Madre del Sur from 500 to 1,820 meters elevation. The species was described by Susana Valencia Ávalos and Oscar Javier Soto Arellano in 2025. It was formerly considered a synonym of Quercus crispifolia. Q. crispifolia differs in having narrowly elliptic leaves, adaxially raised veins, an acute or cuneate base, a long acuminate apex, and an acorn to more than 3 cm long.", where: "Native to the southern Mexican states of Chiapas, Guerrero, and Oaxaca" },
  { year: 2025, group: "Plants", article: "Rubus magurensis", scientific: "Rubus magurensis", said: "Rubus magurensis Wolanin, M.Nobis & Oklej. is a perennial, prickly, deciduous subshrub, a species of blackberry in the genus Rubus (family Rosaceae), native to Poland. The species name is illegitimate. The species is not the same as the earlier described Rubus magurensis Nyár. which is native to Romania. Its native range is limited mainly to the regions of southeastern Poland, within the Northern Carpathians, including the Central Beskids and the Strzyżowskie Foothills.", where: "Native to Poland" },
  { year: 2025, group: "Plants", article: "Ficus naikii", scientific: "Ficus naikii", said: "Ficus naikii, the Kanger Valley fig, is a critically endangered species in the family Moraceae, discovered and described in 2025 from Kanger Valley National Park (KVNP) in the Bastar district of Chhattisgarh. It is endemic to the Bastar division of Chhattisgarh state in central India. The species epithet (naikii) is in the honor of Dr. M. L.", where: "Endemic to the Bastar division of Chhattisgarh state in central India" },
  { year: 2025, group: "Plants", article: "Thorncroftia coddii", scientific: "Thorncroftia coddii", said: "Thorncroftia coddii is an endangered species of Thorncroftia commonly known as the Blyde River Canyon whistlesweet. It was first collected in 1953 by Dr Leslie Codd, who believed it to be Plectranthus succulentus, a species he would later rename Thorncroftia succulenta. It was only in 2025, after more examples were found in the wild, that the plant was described as a new species, distinct from T. succulenta.", where: "Collected in 1953" },
  { year: 2025, group: "Plants", article: "Camellia yangii", scientific: "Camellia yangii", said: "Camellia yangii, commonly known as three‑sepal tea (Chinese: 三萼茶), is a plant species in the tea group (Camellia sect. Thea) of the family Theaceae. It was first described as a new species in 2025. The species is endemic to tropical montane evergreen forests in Malipo County, Yunnan Province, China, and is named for its flower bearing only three sepals (other tea plants typically have five). With fewer than 10 mature individuals in a single population, it is an extremely endangered wild germplasm resource of tea.", where: "Endemic to tropical montane evergreen forests in Malipo County, Yunnan Province, China" },
  { year: 2025, group: "Protists", article: "Hexamita inflata", scientific: "Hexamita inflata", said: "Hexamita inflata is a species of free-living diplomonad that was isolated for the first time from shallow water in a wetland in Řevnice, Czech Republic. This species is found in marine environments where the concentration of oxygen is low, such as sediments of ponds or the water column of marine basins.", where: "Found in marine environments" },
  { year: 2025, group: "Reptiles", article: "Lampropholis isla", scientific: "Lampropholis isla", said: "Lamphropholis isla, also known as the Scawfell Island sunskink, is a species of skink belonging to the subfamily Eugongylinae. It is endemic to the rainforest areas of Scawfell Island off the coast of Queensland, Australia. It is a robust species with the head and body being continuous with almost narrowing of the neck. The snout is rounded and its nasals are widely separated. Their bodies are mostly a uniform light brown color with the occasional darker flecks.", where: "Endemic to the rainforest areas of Scawfell Island off the coast of Queensland, Australia" },
  { year: 2025, group: "Reptiles", article: "Leptophis mystacinus", scientific: "Leptophis mystacinus", said: "Leptophis mystacinus is a species of snake in the family Colubridae endemic to the Cerrado savanna of Brazil. It is one of around 20 named species within the genus Leptophis, and is most similar to L. dibernardoi. L. mystacinus is primarily characterized by its unique color pattern, including a mustache-like pigmented patch on the snout that lends the species its name.", where: "Endemic to the Cerrado savanna of Brazil" },
  { year: 2025, group: "Spiders", article: "Epidelaxia palustris", scientific: "Epidelaxia palustris", said: "Epidelaxia palustris is a species of spider belonging to the genus Epidelaxia. It was described from a specimen collected from the Myristica swamps of Kerala in India. The species phrase palus was derived from the Latin name for swamp, the habitat type from where this spider was first collected.", where: "Described from a specimen collected from the Myristica swamps of Kerala in India" },
  { year: 2025, group: "Spiders", article: "Atrax christenseni", scientific: "Atrax christenseni", said: "Atrax christenseni, the Newcastle funnel-web spider or Newcastle big boy, is a species of venomous mygalomorph funnel-web spider in the family Atracidae, native to an area north of Newcastle in Australia. Its cultural impact is celebrated in a song by Shanty Club, \"Newcastle Big Boy\".", where: "Native to an area north of Newcastle in Australia" },
  { year: 2025, group: "Spiders", article: "Oedothorax simianensis", scientific: "Oedothorax simianensis", said: "Oedothorax simianensis is a species of dwarf spider in the family Linyphiidae, first described in 2025 by Muhammad Irfan, Chang-Cheng Zhang, Yu-Jun Cai, and Zhi-Sheng Zhang. The species is only known from the Simian Shan Mountain Nature Reserve in Chongqing, China.", where: "Known from the Simian Shan Mountain Nature Reserve in Chongqing, China" },
  { year: 2025, group: "Spiders", article: "Neischnocolus samonellaacademy", scientific: "Neischnocolus samonellaacademy", said: "Neischnocolus samonellaacademy is a species of spider in the tarantula family Theraphosidae, found in Ecuador. It was first described in 2025. The species epithet samonellaacademy honours the YouTube channel Sam O'Nella Academy, run by American, Sam A. Miller.", where: "Found in Ecuador" },
  { year: 2025, group: "Spiders", article: "Pilia malenadu", scientific: "Pilia malenadu", said: "Pilia malenadu is a species of jumping spider in the family Salticidae. It was described in 2025 and represents a significant rediscovery of the genus Pilia after 123 years, marking the first time female specimens of this genus have been documented." },
  { year: 2025, group: "Spiders", article: "Yuelushannus baishaensis", scientific: "Yuelushannus baishaensis", said: "Yuelushannus baishaensis is a species of dwarf spider in the family Linyphiidae, described in 2025 by Muhammad Irfan, Chang-Cheng Zhang, Yu-Jun Cai, and Zhi-Sheng Zhang. It is endemic to Baisha in the Jiangjin District of Chongqing, China.", where: "Endemic to Baisha in the Jiangjin District of Chongqing, China" },
  { year: 2024, group: "Amphibians", article: "Xenophrys apatani", scientific: "Xenophrys apatani", said: "Xenophrys apatani, is a species of horned toad of Xenophrys genus, discovered from Arunachal Pradesh in Northeast India. The species is named after Apatani tribe of Arunachal Pradesh. This leaf litter dwelling frog belongs to the family Megophryidae. It is found in Tale Wildlife Sanctuary located in the Lower Subansiri District of Arunachal Pradesh, India. It is dark brown in colour. It is dark brown in colour, with large mottling on the back, and a typical dark triangular patch between the eyes.", where: "Found in Tale Wildlife Sanctuary located in the Lower Subansiri District of Arunachal Pradesh, India" },
  { year: 2024, group: "Amphibians", article: "Zhangixalus thaoae", scientific: "Zhangixalus thaoae", said: "Zhangixalus thaoae, or Thao's tree frog, is a species of frog in the family Rhacophoridae found in Lào Cai province, northwestern Vietnam. It was described by Nguyen et al. in 2024 by specimens found in evergreen montane tropical forest at an elevation of about 1,883 meters above sea level. The species is named after the first author's wife, Nguyen Thi Thanh Thao, as a sign of gratitude for her support of research activities. It mostly resembles Z.", where: "Found in Lào Cai province, northwestern Vietnam" },
  { year: 2024, group: "Amphibians", article: "Phyllobates samperi", scientific: "Phyllobates samperi", said: "Phyllobates samperi, formerly known as sp. aff. aurotaenia, is a species of hypertoxic poison dart frog, once cited as the \"red\" form of Phyllobates aurotaenia. It resembles in size and to some extent in colouration to P. aurotaenia, but genetically it is the sister species of the \"terrible\" frog P. terribilis. It can be distinguished from P." },
  { year: 2024, group: "Amphibians", article: "Brachycephalus dacnis", scientific: "Brachycephalus dacnis", said: "Brachycephalus dacnis is a species of small frog in the family Brachycephalidae endemic to the Atlantic Forest of Brazil. It is one of more than 40 named species within the genus Brachycephalus, and is most similar to B. hermogenesi. B. dacnis is one of the smallest known vertebrates, with the congeneric B. pulex being the only smaller species.", where: "Endemic to the Atlantic Forest of Brazil" },
  { year: 2024, group: "Amphibians", article: "Sphaerotheca varshaabhu", scientific: "Sphaerotheca varshaabhu", said: "Sphaerotheca varshaabhu, commonly known as the Varshaa burrowing frog, is a species of Ranidae family frog which is found in India. The species name is derived from the Sanskrit word 'Varshaabhu'. Varshaa means rain and bhu means taking birth. It signifies its breeding activity only during the rainy season.", where: "Found in India" },
  { year: 2024, group: "Amphibians", article: "Centrolene marcoreyesi", scientific: "Centrolene marcoreyesi", said: "Centrolene marcoreyesi, commonly known as Marco Reyes' glassfrog, is a species of frog in the family Centrolenidae. It is green, with whitish spots and low warts. The species is endemic to Ecuador. Centrolene marcoreyesi was described in 2024, and is named after the herpetologist Marco Miguel Reyes-Puig.", where: "Endemic to Ecuador" },
  { year: 2024, group: "Animals", article: "Skeleton panda sea squirt", scientific: "Clavelina ossipandae", said: "Clavelina ossipandae, the skeleton panda sea squirt or skeleton panda ascidian (Japanese: ガイコツパンダホヤ, romanized: gaikotsu-panda-hoya), is a species of colonial ascidian (sea squirt), a group of sessile, marine filter-feeding invertebrates. Originally discovered near Kume Island in Japan by local divers, pictures of the animal attracted attention in the media for its appearance prior to its formal taxonomic description in 2024." },
  { year: 2024, group: "Animals", article: "Kappa tick", scientific: "Amblyomma kappa", said: "The kappa tick (Amblyomma kappa) is a reptile tick native to parts of subtropical East Asia. It occurs in the Ryukyu Islands of Japan, Taiwan (ROC), and parts of southern China (PRC). Turtles serve as the primary hosts for this species, though it has also occasionally been collected on snakes. Humans are occasionally infested by this species, but these interactions are uncommon and humans are accidental hosts for kappa ticks.", where: "Native to parts of subtropical East Asia" },
  { year: 2024, group: "Animals", article: "Uncus dzaugisi", scientific: "Uncus dzaugisi", said: "Uncus dzaugisi was an organism which lived approximately 560 to 550 million years ago during the late Ediacaran in what is now Southern Australia and Newfoundland and Labrador. Its smooth cylindrical shape, with one end being wider than the other, suggests that it was a member of the clade Ecdysozoa (a group containing arthropods, nematodes and tardigrades, amongst others). If true, this makes it the oldest ecdysozoan known so far, as well as one of the oldest known bilaterians." },
  { year: 2024, group: "Animals", article: "Peripatopsis orientalis", scientific: "Peripatopsis orientalis", said: "Peripatopsis orientalis is a species of velvet worm in the Peripatopsidae family. This species was discovered as one of four clades within the Peripatopsis sedgwicki species complex. Each clade represents a separate species, each with a different geographic distribution in South Africa. The species P. orientalis has the broadest distribution among the four species in this species complex. The specific name refers to the relatively eastern distribution of this species within this species complex." },
  { year: 2024, group: "Animals", article: "Peripatopsis aereus", scientific: "Peripatopsis aereus", said: "Peripatopsis aereus is a species of velvet worm in the family Peripatopsidae. Also known as the Riviersonderend velvet worm, this species is known only from the Riviersonderend Mountains in South Africa. This velvet worm was discovered living in sympatry with another species in the same genus, P. lawrencei. These two sympatric species can be distinguished based on the number of legs: The species P. aereus has 18 pairs of legs, whereas the species P. lawrencei has only 17 leg pairs.", where: "Known only from the Riviersonderend Mountains in South Africa" },
  { year: 2024, group: "Animals", article: "Peripatopsis margaritarius", scientific: "Peripatopsis margaritarius", said: "Peripatopsis margaritarius is a species of velvet worm in the Peripatopsidae family. Also known as the Fort Fordyce velvet worm, this species is a point endemic found only in the Fort Fordyce Nature Reserve in South Africa. This species was discovered as a clade within the Peripatopsis sedgwicki species complex. This velvet worm can have from 21 to 23 pairs of legs, unlike the other three species in the P. sedgwicki species complex, which have only 19 or 20 leg pairs.", where: "Found only in the Fort Fordyce Nature Reserve in South Africa" },
  { year: 2024, group: "Bacteria", article: "Psychrobacter raelei", scientific: "Psychrobacter raelei", said: "Psychrobacter raelei is a gram-negative, strictly aerobic bacterium of the genus Psychrobacter, which was isolated from a dog with peritonitis. The genetic analysis of the original strain (isolated by D. Raele, hence the species' name) placed it in a phylogenetic cluster along with Psychrobacter sanguinis, Psychrobacter piechaudii, and Psychrobacter phenylpyruvicus." },
  { year: 2024, group: "Bacteria", article: "Amycolatopsis carbonis", scientific: "Amycolatopsis carbonis", said: "Amycolatopsis is a genus of high GC-content bacteria within the family Pseudonocardiaceae. The genus is known for producing many types of antibiotics, including Vancomycin, obtained from Amycolatopsis orientalis, is being used for infections resistant to other antibiotics. Amycolatopsis carbonis is an actinobacterium from the genus Amycolatopsis that has been isolated from a coal mining site soil in Mongolia (Nalaikh coal mining site, Nalaikh, Mongolia)." },
  { year: 2024, group: "Bacteria", article: "Amycolatopsis mongoliensis", scientific: "Amycolatopsis mongoliensis", said: "Amycolatopsis mongoliensis is a species of high GC-content bacteria within the family Pseudonocardiaceae. Amycolatopsis mongoliensis, a novel filamentous actinobacterium designated strain 4-36T, exhibiting broad-spectrum antifungal activity, was isolated from a coal mining site in Mongolia (Nalaikh coal mining site)." },
  { year: 2024, group: "Bacteria", article: "Amycolatopsis nalaikhensis", scientific: "Amycolatopsis nalaikhensis", said: "Amycolatopsis nalaikhensis is an actinobacterium from the genus Amycolatopsis that has been isolated from a coal mining site soil in Mongolia (Nalaikh coal mining site, Nalaikh, Mongolia). Amycolatopsis nalaikhensis showed broad antifungal activity against several filamentous fungi and also antibacterial activity against methicillin-resistant Staphylococcus aureus and Acinetobacter baumannii. It was first described by Oyuntsetseg and Kim in 2024." },
  { year: 2024, group: "Beetles", article: "Mecodema haakuturi", scientific: "Mecodema haakuturi", said: "Mecodema haakuturi is a species of ground beetle, restricted to the escarpment of the northeastern arm of the Parataiko Range, western Northland Region, New Zealand. This species is within the curvidens species group, which includes these other species: M. kokoromatua, M. manaia, M. parataiko, M. tenaki, etc. Diagnosis." },
  { year: 2024, group: "Beetles", article: "Pelecium chrissquirei", scientific: "Pelecium chrissquirei", said: "Pelecium chrissquirei is a species of beetle of the family Carabidae. It was formally described in 2024 and is named after the British musician Chris Squire, the bassist of the prog rock band Yes. It is part of the P. rotundipenne species group within its genus. Adults of this small species reach a length of about 7 mm (0.28 in) and have flat, ovular bodies. When viewed from above, they are black and hairless, with light metallic green reflections along the sides. The ventral side is shiny black." },
  { year: 2024, group: "Beetles", article: "Pelecium belloi", scientific: "Pelecium belloi", said: "Pelecium belloi is a species of beetle of the family Carabidae. It was formally described in 2024 and is named after the Brazilian coleopterist Ayr de Moura Bello. It is part of the P. laeve species group within its genus. Adults of this medium-sized species reach a length of about 10 mm (0.39 in) and have flat, ovular bodies. When viewed from above, they are shiny black and hairless, with purple and green reflections on the sides. The ventral side is shiny black. The legs and antennae are reddish-brown." },
  { year: 2024, group: "Beetles", article: "Pelecium buckupi", scientific: "Pelecium buckupi", said: "Pelecium buckupi is a species of beetle of the family Carabidae. It was formally described in 2024 and is named after the Brazilian researcher Ludwig Buckup. It is part of the P. punctatostriatum species group within its genus. Adults of this medium-sized species reach a length of about 12 mm (0.47 in) and have flat, elongate bodies. When viewed from above, they are metallic dark green and hairless, with purple reflections on the sides. The ventral side is shiny black. The legs and antennae are reddish-brown." },
  { year: 2024, group: "Beetles", article: "Pelecium zophos", scientific: "Pelecium zophos", said: "Pelecium zophos is a species of beetle of the family Carabidae. It was formally described in 2024 and is named after its the dark dorsum. It is part of the P. violaceum species group within its genus. Adults of this medium-sized species reach a length of about 13 mm (0.51 in) and have flat, ovular bodies. When viewed from above, they are shiny black and hairless, with purple and green reflections on the sides. The ventral side is shiny black. The legs and antennae are reddish-brown." },
  { year: 2024, group: "Beetles", article: "Pelecium fistulosus", scientific: "Pelecium fistulosus", said: "Pelecium fistulosus is a species of beetle of the family Carabidae. It was formally described in 2024 and is named after its punctate elytral striae. It is part of the P. punctatostriatum species group within its genus. Adults of this large species reach a length of about 16 mm (0.63 in) and have flat, elongate bodies. When viewed from above, they are hairless and shiny black. The ventral side is shiny black. The long, reddish-brown antennae reach the front of the elytra. The legs are black." },
  { year: 2024, group: "Birds", article: "Northern silvery-cheeked antshrike", scientific: "Sakesphoroides niedeguidonae", said: "The northern silvery-cheeked antshrike (Sakesphoroides niedeguidonae) is a species of bird in subfamily Thamnophilinae of family Thamnophilidae, the \"typical antbirds\". It is endemic to northern Brazilian Caatinga habitats and found almost exclusively north of the São Francisco River. Small populations are also reported to be south of the river at Raso da Catarina.", where: "Endemic to northern Brazilian Caatinga habitats and found almost exclusively north of the São Francisco River" },
  { year: 2024, group: "Birds", article: "Timor nightjar", scientific: "Caprimulgus ritae", said: "The Timor nightjar (Caprimulgus ritae) is a species of nightjar in the family Caprimulgidae. It is found in Southeast Asia on the islands of Timor, Rote and Wetar in the Lesser Sunda Islands. It was first described in 2024 by Ben King and collaborators under the binomial name Caprimulgus ritae. The specific epithet ritae was chosen to honour Rita Bobbin, a friend of King. Genetic analysis found that it is most similar to Mees's nightjar (Capimulgus meesi).", where: "Found in Southeast Asia on the islands of Timor, Rote and Wetar in the Lesser Sunda Islands" },
  { year: 2024, group: "Butterflies", article: "Pterourus bjorkae", scientific: "Papilio bjorkae", said: "Pterourus bjorkae (or Papilio bjorkae in some schemes), known as the New England tiger swallowtail, is a species of butterfly belonging to the swallowtail family (Papilionidae), discovered and described in 2024 by entomologist Harry Pavulaan. The species name, bjorkae, honors Icelandic singer, songwriter, and environmentalist Björk, to recognize her artistic influence and her contributions to environmental awareness." },
  { year: 2024, group: "Cephalopods", article: "Insigniteuthis obscura", scientific: "Insigniteuthis obscura", said: "Insigniteuthis obscura is a species of finned cirrate octopus (or flapjack octopus) found along southern and southeastern Australia, over a depth range of 940-1210 m. The species is distinct for males having 2 or 3 massively enlarged suckers on the 2nd - 4th arm pairs (i.e., not present on the dorsal arm pair, but present on all other arms)." },
  { year: 2024, group: "Cephalopods", article: "Opisthoteuthis kerberos", scientific: "Opisthoteuthis kerberos", said: "Opisthoteuthis kerberos, also known as the Kerberos flapjack octopus, is a species of umbrella octopus in the family Opisthoteuthidae. The species is known from 5 specimens collected off the eastern Bass Strait, southeastern Australia in 2000 by the former CSIRO research ship Southern Surveyor. The species is known from a depth of about 2000 meters.", where: "Known from 5 specimens collected off the eastern Bass Strait, southeastern Australia in 2000" },
  { year: 2024, group: "Crustaceans", article: "Gothus teemo", scientific: "Gothus teemo", said: "Gothus teemo is a species of crab and the type species of the genus Gothus. It was discovered in 2024 by Zi-Ming Yuan, Wei Jiang, and Zhong-Li Sha, based on specimens in the South China Sea. It is named after the board game Go as well as the League of Legends playable character Teemo.", where: "Discovered in 2024" },
  { year: 2024, group: "Crustaceans", article: "Pentaceration forkandbrewer", scientific: "Pentaceration forkandbrewer", said: "Pentaceration forkandbrewer is a species of marine isopod in the family Paramunnidae, it is found off the coast of New Zealand, in depths of up to 5,500 m. It was named after a local brewery in Wellington, after winning a contest at a Crustacean conference.", where: "Found off the coast of New Zealand, in depths of up to 5,500 m" },
  { year: 2024, group: "Fish", article: "Leucoraja longirostris", scientific: "Leucoraja longirostris", said: "Leucoraja longirostris, the brown longnose skate, is a medium-sized species of the genus Leucoraja with disc rhombic to (in adult male) evenly inverse heart-shaped, with broadly rounded outer corners and with body length to mid-vent about equal to tail length from mid-vent. Preorbital snout length 17.2–22.3% TL and distance between first gill slits 11.6–12.9% of TL. Orbits moderately large, horizontal diameter 1.0–1.2 times interorbital width." },
  { year: 2024, group: "Fish", article: "Zenarchopterus takaoensis", scientific: "Zenarchopterus takaoensis", said: "Zenarchopterus takaoensis (Takao's garfish) is a species of fish in the family Hemiramphidae. A specimen of Zenarchopterus takaoensis had been displayed at Museum der Natur Hamburg since 1907, with its origin labeled as \"Takao, Formosa,\" referring to place names in use during the period of Japanese rule in Taiwan. Bruce Baden Collette and Jinxiang Su wrote about this specimen in 1986, but did not identify it as a new species at the time." },
  { year: 2024, group: "Fish", article: "Halichoeres sanchezi", scientific: "Halichoeres sanchezi", said: "Halichoeres sanchezi, known by its common name, the tailspot wrasse, is a wrasse in the family Labridae. Halichoeres is a wide-ranging genus; the name comes from the Greek words for salt, alis, and pig, choiros, which likely refers to their blunt snouts. The species epithet sanchezi comes from the scientist who organized the expedition that discovered the species, as well as capturing the first specimen, Professor Carlos Armando Sanchez Ortiz." },
  { year: 2024, group: "Fish", article: "Danio dichromatus", scientific: "Danio dichromatus", said: "Danio dichromatus is a species of freshwater ray-finned fish belonging to the family Danionidae. It was first formally described in 2024 by Ralf Britz and Sven O. Kullander with its type locality given as Melaung Chaung, Palaw Township, Tanintharyi Region in Myanmar at 12°45'26\"N, 98°44'22\". This species was known in the aquarium trade before it was formally described, with the names yellow hikari and blue hikari. This species is known from the drainage systems of the Tanintharyi, Dawei and Lenya rivers in Myanmar.", where: "Known from the drainage systems of the Tanintharyi, Dawei and Lenya rivers in Myanmar" },
  { year: 2024, group: "Fish", article: "Pariolius maldonadoi", scientific: "Pariolius maldonadoi", said: "Pariolius maldonadoi is a species of three-barbeled catfish found in the small creeks and tributaries of the Upper Orinoco and Negro Rivers in Colombia. This species grows to a length of 3.2 centimetres (1.3 in) SL, and inhabits sand and gravel bottoms of creeks of relatively fast flowing water as well as sluggish waters of the same streams where aquatic vegetation is lacking. It feeds mainly on Trichoptera larvae.", where: "Found in the small creeks and tributaries of the Upper Orinoco and Negro Rivers in Colombia" },
  { year: 2024, group: "Fish", article: "Akarotaxis gouldae", scientific: "Akarotaxis gouldae", said: "Akarotaxis gouldae, also known as the banded dragonfish, is a species of ray-finned fish discovered in August 2024 in the Southern Ocean along the continental shelf of Antarctica. Adult specimens measure on average 13 cm (5.1 in) long. The species is characterised by having two dark vertical bands of colour on the sides of the body. They also have a slender body with an elongated mouth and oval-shaped eyes", where: "Discovered in August 2024 in the Southern Ocean along the continental shelf of Antarctica" },
  { year: 2024, group: "Fungi", article: "Tuber cumberlandense", scientific: "Tuber cumberlandense", said: "Tuber cumberlandense, previously referred to as Tuber sp. 66, is an edible fungi species of the genus Tuber. Tuber cumberlandense was named after the Cumberland Plateau in Kentucky and Tennessee where it was found by Margaret Townsend, Lois Martin and Lois' truffle dog, a Lagotto Romagnolo named Monza in January of 2018. T. cumberlandense is endemic to eastern North America, where it has been harvested in truffle orchards and woodlands dominated by broadleaf trees.", where: "Endemic to eastern North America" },
  { year: 2024, group: "Fungi", article: "Tuber canirevelatum", scientific: "Tuber canirevelatum", said: "Tuber canirevelatum is an edible truffle species discovered in 2024 in Tennessee in the United States by Lois Martin and her truffle dog Monza. This species is extremely rare and has only been found in Tennessee. Tuber canirevelatum was named in honor of truffle dogs because they have been essential tools in the cultivation and collection of truffles. The species name 'canirevelatum' is a conjunction of the latin words 'canis' which means \"dog\", and 'revelatum' which means \"to reveal\".", where: "Discovered in 2024 in Tennessee in the United States" },
  { year: 2024, group: "Fungi", article: "Trichosporon austroamericanum", scientific: "Trichosporon austroamericanum", said: "Trichosporon austroamericanum is an anamorphic basidiomycetous yeast species with opportunistic pathogenic potential, formally described in 2024. It was long confused with Trichosporon inkin due to their close phylogenetic relationship, but is now recognized as the second most frequently implicated Trichosporon species in invasive trichosporonosis in France." },
  { year: 2024, group: "Fungi", article: "Simocybe ramosa", scientific: "Simocybe ramosa", said: "Simocybe ramosa is a species of saprotrophic mushroom in the family Crepidotaceae. It was described as new to science in 2024 from a single specimen discovered in the Boston Harbor Islands National Recreation Area in Massachusetts, United States. The species is considered rare and is currently known only from its type location.", where: "Discovered in the Boston Harbor Islands National Recreation Area in Massachusetts, United States" },
  { year: 2024, group: "Fungi", article: "Hydnellum gatesiae", scientific: "Hydnellum gatesiae", said: "Hydnellum gatesiae is a species of mushroom in the family Bankeraceae. It was described by James K. Douch, Luke J. Vaughan, and Tom W. May in 2024. The specific epithet refers to Genevieve M. Gates, who collected all specimens used in the species description. The type locality is Kermandie Falls, Australia." },
  { year: 2024, group: "Fungi", article: "Hydnellum nothofagacearum", scientific: "Hydnellum nothofagacearum", said: "Hydnellum nothofagacearum is a species of mushroom in the family Bankeraceae. It was described by James K. Douch and Jerry A. Cooper in 2024. The specific epithet refers to Nothofagaceae, with which these fungi are associated. The type locality is in Nelson Lakes National Park, New Zealand." },
  { year: 2024, group: "Insects", article: "Syntretus perlmani", scientific: "Syntretus perlmani", said: "Syntretus perlmani is a species of parasitic wasps of adult Drosophila. It is currently the only known parasitoid wasp that targets adult flies, as opposed to their larval or pupal stages. It has been identified across the eastern USA. S. perlmani is an endoparasite. Female wasps lay a single egg in the abdomen of adult flies. Post oviposition, the larval stage of the wasp lasts around 18 days, with infection of the fly visible with the naked eye (i.e. without dissection) after 7 days." },
  { year: 2024, group: "Insects", article: "Paraparatrechina neela", scientific: "Paraparatrechina neela", said: "Paraparatrechina neela is a species of small ants in the subfamily Formicinae and the genus Paraparatrechina. Discovered in 2024, it is only known from India. It is a small ant, having a total body length of less than 2 mm (0.079 in). Its body is predominantly metallic blue in color, except for the antennae, mandibles, eyes, and legs. Consequently, it is known as the blue ant. P.", where: "Discovered in 2024, it is only known from India" },
  { year: 2024, group: "Insects", article: "Leptanilla voldemort", scientific: "Leptanilla voldemort", said: "Leptanilla voldemort is a species of ant in the genus Leptanilla and was described in 2024. It was named after the Harry Potter villain, Lord Voldemort. This species was found in the Pilbara region in the Western Australian outback. This species is said to live underground and is described as having an extremely \"ghostly and slender\" appearance, as well as having sharp mandibles. Researchers are hoping that this scientific discovery will bring to light a better understanding of subterranean ants.", where: "Found in the Pilbara region in the Western Australian outback" },
  { year: 2024, group: "Insects", article: "Andrena androfovea", scientific: "Andrena androfovea", said: "Andrena androfovea is a species of miner bee in the family Andrenidae from Texas and Oklahoma, characterized by its metallic dark blue to blue-green and distinctive coarse punctation. First observed in the late 1980s, it was formally described as a new species in 2024. Genetic analyses revealed that Andrena androfovea represents a distinct lineage within the genus Andrena, leading to the creation of a new subgenus. Unique among Andrena species, Andrena androfovea primarily feeds on flowers of the family Solanaceae." },
  { year: 2024, group: "Insects", article: "Ropalidia chromis", scientific: "Ropalidia chromis", said: "Ropalidia chromis is a species of polistine wasp that belongs to the tribe Ropalidiini. It is native to central Africa in areas such as the DR Congo and the Republic of Congo. This species has an ambiguous relationship with other members of genus Ropalidia. It has characteristic of both the capensis and non-capensis species groups along with traits that are prevalent in other Polistinae genera with the most notable similarities with Polistes.", where: "Native to central Africa in areas such as the DR Congo and the Republic of Congo" },
  { year: 2024, group: "Insects", article: "Scaralina cristata", scientific: "Scaralina cristata", said: "Scaralina cristata is a species of planthopper in the family Fulgoridae. It is found from Arizona in the United States south to the Sierra Madre Occidental in Mexico. It is one of four species (the others being Scaralina aethrinsula, Scaralina marmorata, and Scaralina metcalfi) that were, for several decades, erroneously grouped together under a single name, Alphina glauca; this name is now treated as a synonym of S. marmorata." },
  { year: 2024, group: "Lichens", article: "Inoderma applanatum", scientific: "Inoderma applanatum", said: "Inoderma applanatum is a species of crustose lichen in the family Arthoniaceae. It forms thin, whitish-grey patches that can spread over 30 cm across on bark, with broad, flattened, reddish-brown to grey-brown fruiting bodies typically 0.5–2 mm wide. The species is known from Tasmania and coastal Victoria, where it grows mainly on the papery bark of swamp paperbark (Melaleuca ericifolia) in coastal lowland woodlands. It was described in 2024 as part of the first documentation of the genus Inoderma in Australasia.", where: "Known from Tasmania and coastal Victoria" },
  { year: 2024, group: "Lichens", article: "Dictyomeridium neureuterae", scientific: "Dictyomeridium neureuterae", said: "Dictyomeridium neureuterae is a species of corticolous (bark-dwelling) lichen in the family Trypetheliaceae. Found on Ōtata Island in the Noises group of islands in the Hauraki Gulf of New Zealand, it was formally described as a new species in 2024. The lichen has been found on the bark of Pseudopanax lessonii.", where: "Found on Ōtata Island in the Noises group of islands in the Hauraki Gulf of New Zealand, it was formally described as a" },
  { year: 2024, group: "Lichens", article: "Lithothelium kiritea", scientific: "Lithothelium kiritea", said: "Lithothelium kiritea is a species of corticolous (bark-dwelling) lichen in the family Pyrenulaceae. Found in New Zealand, it was formally described as a new species in 2024. The lichen exclusively grows on the bark of Cordyline australis.", where: "Found in New Zealand, it was formally described as a new species in 2024" },
  { year: 2024, group: "Mammals", article: "Crocidura balingka", scientific: "Crocidura balingka", said: "Crocidura balingka, the Balingka white-toothed shrew, is a species of shrew in the genus Crocidura known from Mount Singgalang on Sumatra, where it occurs only above 2,000 metres (6,600 ft). It is named after the people of the village of Balingka in Agam Regency for their assistance to biologists studying the local fauna. The species was first described in 2024 by a team of scientists from the United States and Indonesia.", where: "Known from Mount Singgalang on Sumatra" },
  { year: 2024, group: "Mammals", article: "Western delicate mouse", scientific: "Pseudomys pilbarensis", said: "The western delicate mouse (Pseudomys pilbarensis), also known as the Pilbara delicate mouse or Kalunyja in the Kariyarra language, is a species of rodent native to Australia in the family Muridae. The species occurs in the Pilbara, Great Sandy Desert, and south-eastern Kimberley regions of Western Australia.", where: "Native to Australia in the family Muridae" },
  { year: 2024, group: "Mammals", article: "Pudella carlae", scientific: "Pudella carlae", said: "Pudella carlae, the Peruvian Yungas pudu, is a species of deer from Peru. It was found in 2024 to be a distinct species from the northern pudu, from which it is separated geographically by the Huancabamba Depression. It is the first living deer species to be described in the 21st century.", where: "Found in 2024 to be a distinct species from the northern pudu, from" },
  { year: 2024, group: "Moths", article: "Carmenta brachyclados", scientific: "Carmenta brachyclados", said: "Carmenta brachyclados is a moth of the family Sesiidae. It was described by Mark Sterling and David Lees in 2024. It is native to Guyana. It was discovered after a woman from Wales uploaded a photo of the moth in her home after it had been caught in her luggage and traveled with her from Guyana.", where: "Native to Guyana" },
  { year: 2024, group: "Plants", article: "Nepenthes pongoides", scientific: "Nepenthes pongoides", said: "Nepenthes pongoides is a tropical pitcher plant endemic to the Meliau Range, in central Sabah, Malaysia. The species is notable for its large size, making it one of the largest species of Nepenthes described in recent years. Additionally, the species is characterized by peltate tendril exertion and absence of upper pitchers.", where: "Endemic to the Meliau Range, in central Sabah, Malaysia" },
  { year: 2024, group: "Plants", article: "Nepenthes kampalili", scientific: "Nepenthes kampalili", said: "Nepenthes kampalili is a tropical pitcher plant endemic to Mt. Kampalili, in Maragusan, province of Davao de Oro, in Mindanao. This species was compared with Nepenthes peltata Sh.Kurata. Nepenthes kampalili differs from N. peltata in its tendril that are apically attached to the leaf, its densely pubescent ground pitchers, pitcher lid that is densely pubescent, and 2 pitcher spur that occasionally arise in the posterior midsection of peristome neck, whereas in N." },
  { year: 2024, group: "Plants", article: "Vincetoxicum nakaianum", scientific: "Vincetoxicum nakaianum", said: "Vincetoxicum nakaianum (Japanese tachi-gashiwa) is a species of dogbane in the family Apocynaceae that is native to Japan. Originally discovered in 1937 by Takenoshin Nakai but incorrectly as Cynanchum magnificum, it was rediscovered and described in 2024 by Ko Mochizuki and Tetsuo Ohi-Toma. In 2025, it was discovered that the plant a scent that smells like dying ants – a strategy it uses for attracting flies for its pollination. It is the first plant known to specifically mimic ant odour for reproduction.", where: "Native to Japan" },
  { year: 2024, group: "Plants", article: "Lomelosia comosa", scientific: "Lomelosia comosa", said: "Lomelosia comosa (most authorities continue to use its synonym Scabiosa comosa), the northeastern scabious, is a species of flowering plant in the family Caprifoliaceae. It is native to southern Siberia, Mongolia, north and east central China, and Korea. A perennial herb reaching 30 to 80 cm (12 to 31 in), it is typically found growing in dry areas such as dunes, slopes, and steppes at elevations from 300 to 1,600 m (1,000 to 5,200 ft). It is the national flower of Mongolia.", where: "Native to southern Siberia, Mongolia, north and east central China, and Korea" },
  { year: 2024, group: "Plants", article: "Dudleya chasmophyta", scientific: "Dudleya chasmophyta", said: "Dudleya chasmophyta, commonly known as the Santiago Canyon liveforever or the crevice live-forever, is a rare succulent endemic to Orange County, California. It is known from a single population occupying a steep cliff band. When first classified this population was originally lumped with Dudleya cymosa ssp. ovatifolia, but genomic testing led to Dudleya chasmophyta's confirmation as a separate species in 2024. It has yellow flowers and blooms late spring - early summer.", where: "Endemic to Orange County, California" },
  { year: 2024, group: "Plants", article: "Quercus purhepecha", scientific: "Quercus purhepecha", said: "Quercus purhepecha is a species of oak endemic to the state of Michoacán in western Mexico. It is a low rhizomatous shrub, 0.3 to 0.7 meters tall. It is known only from the Lake Cuitzeo Basin in the Trans-Mexican Volcanic Belt from 2,100 to 2,400 meters elevation. The species was described by Oscar Angel De Luna-Bonilla, Susana Valencia Ávalos, and Allen James Coombes in 2024. The species is named for the Purépecha people indigenous to the species' native region.", where: "Endemic to the state of Michoacán in western Mexico" },
  { year: 2024, group: "Protists", article: "Naegleria lustrarea", scientific: "Naegleria lustrarea", said: "Naegleria lustrarea is a species of free-living amoeba belonging to the group Heterolobosea. It was described in 2024 from amoebae present in the gut of a salamander found in Arkansas. It is an amoeboflagellate, capable of transitioning from an amoeboid stage to a flagellate stage during its life cycle.", where: "Found in Arkansas" },
  { year: 2024, group: "Reptiles", article: "Bothriechis khwargi", scientific: "Bothriechis khwargi", said: "Bothriechis khwargi, also known as Khwarg’s eyelash-pitviper, is a species of pit viper in the family Viperidae. It was described in 2024, alongside 4 other species in its genus, by the Ecuadorian-Venezuelan herpetologist Alejandro Arteaga and his colleagues. It is named after Juewon Khwarg to honor his work discovering and protecting new species of vipers in the Colombian Andes." },
  { year: 2024, group: "Reptiles", article: "Bothriechis rahimi", scientific: "Bothriechis rahimi", said: "Bothriechis rahimi is a species of pit viper described in 2024. It is known from the Chocó biome of southwestern Colombia and extreme northwestern Ecuador. Bothriechis rahimi is an arboreal snake occurring in evergreen lowland forests, usually not far from the coast. It can grow to a total length of 336 mm (13.2 in) in males and 494 mm (19.4 in) in females.", where: "Known from the Chocó biome of southwestern Colombia and extreme northwestern Ecuador" },
  { year: 2024, group: "Reptiles", article: "Bothriechis rasikusumorum", scientific: "Bothriechis rasikusumorum", said: "Bothriechis rasikusumorum is a species of pit viper described in 2024. It is only known from the Río Magdalena watershed in Huila Department, Colombia, from the slopes of both Cordillera Central and Cordillera Oriental. Bothriechis rasikusumorum is an arboreal snake that can grow to a total length of 650 mm (26 in) in males and 799 mm (31.5 in) in females." },
  { year: 2024, group: "Reptiles", article: "Brookesia nofy", scientific: "Brookesia nofy", said: "Brookesia nofy is a species of tiny chameleon, a lizard in the genus Brookesia. The species is found in Ankanin’ny Nofy, Madagascar. B. nofy can grow up to 33 millimetres (1.3 in) in length, making it one of the world's smallest reptiles. This species, like others in the Brookesia genus, is known for its small size and cryptic coloration.", where: "Found in Ankanin’ny Nofy, Madagascar" },
  { year: 2024, group: "Reptiles", article: "Diploderma daduense", scientific: "Diploderma daduense", said: "Diploderma daduense is a species of lizard in the genus Diploderma of the Agamidae family. This species was reported from lower Dadu River Valley, Sichuan Province, Western China. D. daduense shows a unique combination of morphological attributes and distinct genetic divergence compare with near relatives." },
  { year: 2024, group: "Reptiles", article: "Abronia cunemica", scientific: "Abronia cunemica", said: "Abronia cunemica, also known commonly as the Coapilla arboreal alligator lizard and el dragoncito de Coapilla in Mexican Spanish, is a species of lizard in the family Anguidae. The species, which was described in 2024 by Adam Clause et al., is native to southern Mexico.", where: "Native to southern Mexico" },
  { year: 2024, group: "Spiders", article: "Rhene eximia", scientific: "Rhene eximia", said: "Rhene eximia is a species of jumping spider in the genus Rhene that lives in the forests of Uganda. A beetle-like spider, it has a forward section, or cephalothorax, that is between 2.3 and 2.5 mm (0.09 and 0.10 in) long and, behind that, an abdomen that is between 2.8 and 3.5 mm (0.11 and 0.14 in) long. Its carapace, the hard upper part of the cephalothorax has a characteristic shape, being oval rather than round or trapezoidal.", where: "Lives in the forests of Uganda" },
  { year: 2024, group: "Spiders", article: "Rhene hexagon", scientific: "Rhene hexagon", said: "Rhene hexagon is a species of jumping spider that lives in the forests of Uganda. A beetle-like member of the genus Rhene, the spider has a forward section, or cephalothorax, that is between 1.8 and 2 mm (0.07 and 0.08 in) long and, behind that, an abdomen that is between 2.2 and 2.5 mm (0.09 and 0.10 in) long. The top of its cephalothorax, its carapace, has a characteristic shape, being in the form of a hexagon, which is reflected in the species' specific name.", where: "Lives in the forests of Uganda" },
  { year: 2024, group: "Spiders", article: "Rhene amabilis", scientific: "Rhene amabilis", said: "Rhene amabilis is a species of jumping spider in the genus Rhene that lives in the forests of Uganda. The spider's specific name means 'attractive'. A beetle-like spider, it has a cephalothorax that is between 1.6 and 1.9 mm (0.06 and 0.07 in) long and an abdomen that is between 1.7 and 2.2 mm (0.07 and 0.09 in) long. It is generally brown, apart from its darker sternum, with a large pitted eye field and darker brown stripe on the top of its abdomen. Its spinnerets are yellowish-grey.", where: "Lives in the forests of Uganda" },
  { year: 2024, group: "Spiders", article: "Progradungula barringtonensis", scientific: "Progradungula barringtonensis", said: "Progradungula barringtonensis is a species of cribellate spider endemic to the Barrington Tops National Park of New South Wales, Australia. It is one of only three species in the gradungulid genus Progradungula. At the time of description only an adult male and a number of juveniles were known. Progradungula has been described as a \"ghost of Gondwana\", surviving through several mass extinctions in relictual populations across Australia.", where: "Endemic to the Barrington Tops National Park of New South Wales, Australia" },
  { year: 2024, group: "Spiders", article: "Phormingochilus hatihati", scientific: "Phormingochilus hatihati", said: "Phormingochilus hatihati, formerly known under the names Cyriopagopus sp. 'hati hati' and Omothymus sp. 'hati hati', commonly known as the purple earth tiger, the Sulawesi violet tarantula, or erroneously as the Borneo purple, is a species of spider in the tarantula family Theraphosidae, found on the island of Sulawesi. It was first described by Simon Müller et al. in 2024.", where: "Found on the island of Sulawesi" },
  { year: 2024, group: "Spiders", article: "Liphistius dawei", scientific: "Liphistius dawei", said: "Liphistius dawei is a species of trapdoor spider native to Myanmar. The species name refers to the type locality of this species which is the Dawei State of Myanmar. Males have a carapace that is uniformly brown with black stripe along the margins. The chelicerae are a pale color while the palp and legs are more of a pale brown color.", where: "Native to Myanmar" },
];
